"use strict";(self.webpackChunkmystic_auth_docs=self.webpackChunkmystic_auth_docs||[]).push([["385"],{3842(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>l,frontMatter:()=>o,contentTitle:()=>r,toc:()=>h,assets:()=>c});var s=JSON.parse('{"id":"mystic_auth/testing/coverage-authentication","title":"What the Authentication Tests Cover","description":"---","source":"@site/docs/mystic_auth/testing/coverage-authentication.md","sourceDirName":"mystic_auth/testing","slug":"/mystic_auth/testing/coverage-authentication","permalink":"/mystic-auth-docs/docs/mystic_auth/testing/coverage-authentication","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"Testing Overview","permalink":"/mystic-auth-docs/docs/mystic_auth/testing/overview"},"next":{"title":"What the Authorization (PBAC) Tests Cover","permalink":"/mystic-auth-docs/docs/mystic_auth/testing/coverage-authorization"}}'),i=n(4848),a=n(8453);let o={},r="What the Authentication Tests Cover",c={},h=[{value:"Signup and account verification",id:"signup-and-account-verification",level:2},{value:"Login",id:"login",level:2},{value:"Logout and logout-all",id:"logout-and-logout-all",level:2},{value:"OAuth2 and PKCE",id:"oauth2-and-pkce",level:2},{value:"Password reset",id:"password-reset",level:2},{value:"Refresh tokens and session rotation",id:"refresh-tokens-and-session-rotation",level:2},{value:"Rate limiting and lockout",id:"rate-limiting-and-lockout",level:2},{value:"Session and cookie handling",id:"session-and-cookie-handling",level:2}];function d(e){let t={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",p:"p",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"what-the-authentication-tests-cover",children:"What the Authentication Tests Cover"})}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsxs)(t.p,{children:["This page walks through what the test suite actually checks for signup,\nlogin, logout, password reset, OAuth2, refresh tokens, and rate limiting. It\ndoes not list file names or counts; see ",(0,i.jsx)(t.a,{href:"/mystic-auth-docs/docs/mystic_auth/testing/overview",children:"Testing Overview"})," for\nthat. For how these flows work, see\n",(0,i.jsx)(t.a,{href:"/mystic-auth-docs/docs/mystic_auth/authentication/overview",children:"Authentication Overview"}),"."]}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"signup-and-account-verification",children:"Signup and account verification"}),"\n",(0,i.jsxs)(t.p,{children:["Tests cover the full signup path: a new signup sends a verification email and\nalways returns the same generic response, whether or not the email was\nalready registered, so an attacker cannot use signup to find out which\nemails exist. A duplicate signup does not create a second user or send a\nsecond email, and this holds even when the duplicate is submitted with\ndifferent letter casing (",(0,i.jsx)(t.code,{children:"Test@example.com"})," vs ",(0,i.jsx)(t.code,{children:"test@example.com"}),")."]}),"\n",(0,i.jsx)(t.p,{children:"The account gets its default self-service policy assigned on creation, and\nsignup still succeeds even if that default policy is missing from the\ndatabase, rather than failing the whole signup."}),"\n",(0,i.jsx)(t.p,{children:"Verification tokens are single-use: a token can confirm an account exactly\nonce, and a second attempt with the same token is rejected. The route no\nlonger accepts a token passed as a query string, only in the request body.\nThere is also a concurrency test that fires many signup-then-verify chains\nat once, sequentially and in parallel, and checks a legitimate fresh\nverification token is never rejected by a race with itself."}),"\n",(0,i.jsxs)(t.p,{children:["See ",(0,i.jsx)(t.a,{href:"/mystic-auth-docs/docs/mystic_auth/authentication/signup-and-verification",children:"Signup and Verification"}),"\nfor the full flow."]}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"login",children:"Login"}),"\n",(0,i.jsx)(t.p,{children:"Login is checked against wrong password, unknown email, unverified account,\ndeactivated account, and OAuth-only account (no password set) cases. A login\nattempt against a nonexistent user still performs a password hash\ncomparison using a dummy hash, so response timing does not reveal whether\nthe email exists. The same timing-safety property is checked for unverified\naccounts."}),"\n",(0,i.jsxs)(t.p,{children:["Casing is normalized: a user who signed up as ",(0,i.jsx)(t.code,{children:"Test@example.com"})," can log in\nas ",(0,i.jsx)(t.code,{children:"test@example.com"}),"."]}),"\n",(0,i.jsx)(t.p,{children:'Lockout is tested from both directions: failed attempts accumulate towards a\nlockout threshold, a successful login resets the counter, and once locked,\neven the correct password is rejected. The account-level lock and the\nsource-IP-level lock are both checked independently, and the "locked out,\ntry again in N minutes" response is identical whether the pre-check or the\npost-check caught the lockout, so the response itself does not leak which\none triggered. The retry-time estimate never reports zero minutes for an\naccount that is still actually locked.'}),"\n",(0,i.jsxs)(t.p,{children:["See ",(0,i.jsx)(t.a,{href:"/mystic-auth-docs/docs/mystic_auth/authentication/login",children:"Login"}),"."]}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"logout-and-logout-all",children:"Logout and logout-all"}),"\n",(0,i.jsx)(t.p,{children:"Logout revokes the presented refresh token and clears both auth cookies,\nincluding when the token is already revoked or fails to decode at all,\nthose responses still succeed and still clear cookies rather than leaking a 500. Logout writes an accurate audit entry in both cases, including when the\ntoken cannot be decoded (the entry is recorded without an email in that\ncase)."}),"\n",(0,i.jsx)(t.p,{children:"Logout-all revokes every session for the account by bumping the account's\ntoken version, so already-issued access tokens stop working immediately,\nnot just the refresh token. It is tested against the same edge cases as\nsingle logout: undecodable tokens, already-revoked tokens, and no active\nsessions at all, still return success and clear cookies. If the version\nbump itself cannot be confirmed (for example a Redis hiccup), the route\nreturns a 503 rather than reporting success on an unconfirmed revocation."}),"\n",(0,i.jsxs)(t.p,{children:["See ",(0,i.jsx)(t.a,{href:"/mystic-auth-docs/docs/mystic_auth/authentication/logout",children:"Logout"}),"."]}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"oauth2-and-pkce",children:"OAuth2 and PKCE"}),"\n",(0,i.jsx)(t.p,{children:"The Google OAuth2 login flow is tested end to end: a brand-new Google login\ncreates a verified user with no password, and a Google login for an\nexisting email links the accounts. Linking behavior is specific about\npassword handling: an unverified password account gets its password cleared\nwhen Google verifies the same email (so an attacker who pre-registered the\nvictim's email cannot keep using a stale password), but an already-verified\naccount's password is left untouched by a later Google login."}),"\n",(0,i.jsx)(t.p,{children:"PKCE (Proof Key for Code Exchange) is checked for correctness: the code\nverifier is hashed with SHA-256 and sent as the challenge, and a mismatched\nverifier fails closed with no user created, end to end. OAuth state tokens\nare single-use and tied to a cookie; a state/cookie mismatch, a missing\nstate, and a replayed state are all rejected, and Google reporting an\nunverified email is rejected outright. A user cancelling the Google consent\nscreen redirects cleanly back to the app instead of surfacing a raw 422."}),"\n",(0,i.jsxs)(t.p,{children:["See ",(0,i.jsx)(t.a,{href:"/mystic-auth-docs/docs/mystic_auth/authentication/oauth2-pkce",children:"OAuth2 and PKCE"}),"."]}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"password-reset",children:"Password reset"}),"\n",(0,i.jsx)(t.p,{children:"Requesting a reset persists a single-use reset token. Confirming a reset\nconsumes the token, revokes the account's existing sessions, and rejects a\nreused or unknown token. A concurrent double-submit of the same reset token\nis checked to let only one request through."}),"\n",(0,i.jsx)(t.p,{children:"Retry-friendliness is specifically tested: if the new password is weak, the\naccount already had that password, or the database write fails, the\noriginal reset token is restored so the user can retry without requesting a\nbrand new email. The restored token's remaining lifetime is capped by\nwhatever time was actually left on the original JWT, it is never extended."}),"\n",(0,i.jsxs)(t.p,{children:["See ",(0,i.jsx)(t.a,{href:"/mystic-auth-docs/docs/mystic_auth/authentication/password-reset",children:"Password Reset"}),"."]}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"refresh-tokens-and-session-rotation",children:"Refresh tokens and session rotation"}),"\n",(0,i.jsx)(t.p,{children:"Refresh tokens rotate on every use: the old token is rejected once a new one\nhas been issued. A concurrent replay of the exact same refresh token only\nlets one of the simultaneous requests through. Reusing an already-rotated\n(stale) token is treated as a compromise signal and revokes the affected\nsession chain, tests check this revocation is scoped to just that chain when\nchain information is available, and falls back to revoking everything for\nthe account when it is not (an older token minted before chain tracking\nexisted). Type confusion is rejected: presenting an access token where a\nrefresh token is expected (and vice versa) fails without being mistaken for\nreuse abuse. A genuinely expired refresh token is also rejected. Repeated,\nlegitimate refreshes do not themselves trip the failed-attempt lockout meant\nfor guessing attacks."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"rate-limiting-and-lockout",children:"Rate limiting and lockout"}),"\n",(0,i.jsx)(t.p,{children:"The IP-based and account-based rate limiters are tested as independent keys,\nan attacker cannot dodge an account lock by rotating IPs, or lock out a\nvictim by hammering just the IP key. The limiter is checked to fail closed:\nif Redis itself is unreachable, requests are rejected (429) rather than let\nthrough unchecked. A failure inside the optional account-extractor callback\nis logged but does not crash the request. Expiry (TTL) on a rate-limit\ncounter is only set on the very first request in a window, not reset on\nevery subsequent one."}),"\n",(0,i.jsxs)(t.p,{children:["Client IP resolution is tested against proxy spoofing: with no trusted\nproxies configured the raw TCP peer address is used; with trusted proxies\nconfigured, the right-most ",(0,i.jsx)(t.code,{children:"X-Forwarded-For"})," entry contributed by a trusted\nhop is used, and entries a caller could forge earlier in the chain are\nignored, including a multi-hop chain where every forwarded entry claims to\nbe a trusted hop itself."]}),"\n",(0,i.jsxs)(t.p,{children:["See ",(0,i.jsx)(t.a,{href:"/mystic-auth-docs/docs/mystic_auth/security/hardening",children:"Security Hardening"})," for how rate limiting fits\nthe wider abuse-prevention picture."]}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"session-and-cookie-handling",children:"Session and cookie handling"}),"\n",(0,i.jsxs)(t.p,{children:["Both the access and refresh token cookies are checked to carry the expected\nsecurity flags (",(0,i.jsx)(t.code,{children:"Secure"}),", matching ",(0,i.jsx)(t.code,{children:"SameSite"}),"), and their max-age values are\nderived from settings rather than hardcoded. The refresh token cookie is\nspecifically scoped to the auth path only, so it is not sent on every\nrequest, while the access token cookie is not path-restricted. Clearing\ncookies on logout is checked to use a matching ",(0,i.jsx)(t.code,{children:"SameSite"})," and the same\nscoped path, so the browser actually deletes the cookie that was set (a\nmismatched clear-cookie call silently fails to remove it)."]}),"\n",(0,i.jsxs)(t.p,{children:["See ",(0,i.jsx)(t.a,{href:"/mystic-auth-docs/docs/mystic_auth/authentication/session-management",children:"Session Management"})," for the\nmanage-sessions dashboard covered in\n",(0,i.jsx)(t.a,{href:"/mystic-auth-docs/docs/mystic_auth/testing/coverage-users-and-sessions",children:"coverage-users-and-sessions.md"}),"."]}),"\n",(0,i.jsx)(t.hr,{})]})}function l(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>o,x:()=>r});var s=n(6540);let i={},a=s.createContext(i);function o(e){let t=s.useContext(a);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),s.createElement(a.Provider,{value:t},e.children)}}}]);